    'resources.chapter.government.title':
      'Puerta de entrada a la gobernanza nacional',
    'resources.chapter.government.story':
      "En febrero de 2020, ingenieros taiwaneses crearon un mapa de disponibilidad de mascarillas en tiempo real durante un fin de semana, conectando 6.000 farmacias. Una persona, una laptop, 72 horas — posible gracias a que data.gov.tw ofrece más de 50.000 conjuntos de datos gubernamentales listos para que cualquiera los use en cualquier momento. Taiwán escribió la 'transparencia de gobernanza' en cada API descargable.",
    'resources.chapter.culture.title': 'Cultura y conocimiento',
    'resources.chapter.culture.story':
      'En menos de 36.000 kilómetros cuadrados, Taiwán alberga 159 universidades, más de 500 museos, 9 parques nacionales, desde la Montaña de Jade de 3.952 metros hasta costas de arrecifes de coral. El Museo Nacional del Palacio guarda cerca de 700.000 tesoros culturales chinos, mientras que los festivales de templos vecinales son igualmente patrimonio cultural vivo. La densidad cultural de esta isla supera con creces su tamaño en el mapa.',
    'resources.chapter.media.title': 'Voces de Taiwán',
    'resources.chapter.media.story':
      'En 1995, estudiantes de la NTU montaron un servidor BBS en su residencia, llamándolo PTT. Treinta años después, este foro de texto plano sigue siendo la plataforma de discusión pública más influyente de Taiwán — durante el Movimiento del Girasol de 2014, PTT fue la fuente de información en tiempo real más rápida y completa. El ecosistema mediático de Taiwán, desde periódicos convencionales hasta foros de internautas, lucha por la voz de la democracia en cada nivel.',
    'resources.chapter.economy.title': 'Economía y motor de vida',
    'resources.chapter.economy.story':
      "Cada dos smartphones en el mundo contienen un chip fabricado por TSMC — los expertos en geopolítica lo llaman el 'escudo de silicio'. Pero los chips son solo la punta del iceberg: 99,9% de cobertura sanitaria universal, una tienda de conveniencia cada 2,3 kilómetros cuadrados, trenes bala de 90 minutos de Taipéi a Kaohsiung. Lo que sostiene 23 millones de vidas diarias es un sistema de precisión tan perfecto que apenas notas que está ahí.",
    'resources.chapter.community.title': 'Tecnología cívica y comunidad',
    'resources.chapter.community.story':
      "El lema de g0v: 'No preguntes por qué nadie lo hace — tú eres ese nadie.' Mapas de mascarillas, bots de verificación de hechos, rastreadores de promesas electorales — todos nacidos de hackatones de fin de semana. En Taiwán, la participación cívica se ve así: escribir código, abrir issues, enviar pull requests. COMPUTEX.md es producto de este mismo espíritu.",
    'resources.insight.gov.branches.number': '5',
    'resources.insight.gov.branches.label': 'Poderes constitucionales',
