    'resources.sub.fiveYuan': 'Poderes constitucionales',
    'resources.sub.fiveYuan.desc':
      'Estos cinco poderes forman el sistema pentapartito único de Taiwán — el único de su tipo en el mundo.',
    'resources.sub.ministries': 'Ministerios y agencias',
    'resources.sub.ministries.desc':
      'Desde el Ministerio de Asuntos Digitales hasta el Consejo de Pueblos Indígenas, cada ministerio mantiene su propio portal de datos abiertos.',
    'resources.sub.localGov': 'Gobiernos locales',
    'resources.sub.localGov.desc':
      '22 condados y ciudades, 22 estilos de gobernanza local. La carrera por la ciudad inteligente entre los seis municipios especiales está redefiniendo los servicios públicos.',
    'resources.sub.openData': 'Datos abiertos',
    'resources.sub.openData.desc':
      'Aquí es donde comienzan los milagros de la tecnología cívica de Taiwán. Mapas de mascarillas, citas de vacunación, monitoreo de calidad del aire — todo empezó desde estas plataformas.',
    'resources.sub.universities': 'Principales universidades e investigación',
    'resources.sub.universities.desc':
      'Las universidades de Taiwán no solo enseñan — el laboratorio de computación cuántica de la NTU y el centro de investigación en semiconductores de la NCKU son nodos vitales en la red académica global.',
    'resources.sub.museums': 'Museos y bibliotecas',
    'resources.sub.museums.desc':
      'Desde la Col de Jade del Museo Nacional del Palacio hasta la colección de violines del Museo Chimei, los museos de Taiwán son portales a través del tiempo y el espacio.',
    'resources.sub.venues': 'Espacios artísticos y culturales',
    'resources.sub.venues.desc':
      'El ecosistema artístico de Taiwán está despegando. C-LAB, Teatro Nacional, Weiwuying — una concentración de espacios de clase mundial que rivaliza con Nueva York.',
    'resources.sub.parks': 'Parques nacionales y áreas escénicas',
    'resources.sub.parks.desc':
      'Desde el nivel del mar hasta los 3.952 metros, los 9 parques nacionales de Taiwán abarcan todas las zonas climáticas de la Tierra. En un solo día, puedes pasar de arrecifes de coral tropicales a líneas de nieve alpina.',
    'resources.sub.mainstream': 'Medios convencionales',
    'resources.sub.mainstream.desc':
      'Desde la levantación de las prohibiciones de prensa tras el fin de la ley marcial en 1988, hasta la competencia actual de canales de noticias 24 horas — la libertad de prensa de Taiwán se ganó con esfuerzo.',
    'resources.sub.digital': 'Medios nativos digitales',
    'resources.sub.digital.desc':
      'Mientras los medios tradicionales luchan, los medios nativos digitales de Taiwán están redefiniendo el periodismo. El modelo sin fines de lucro de The Reporter demuestra que el periodismo de investigación puede sobrevivir sin publicidad.',
    'resources.sub.ngo': 'Sociedad civil y ONG',
    'resources.sub.ngo.desc':
      'Taiwán tiene la mayor densidad de ONG de Asia. Desde el medio ambiente hasta los derechos humanos, estas organizaciones no solo vigilan al gobierno — a menudo van a la vanguardia.',
    'resources.sub.companies': 'Líderes de la industria',
    'resources.sub.companies.desc':
      'Desde TSMC hasta Foxconn, estas empresas aparecen en informes de cadenas de suministro en todo el mundo.',
    'resources.sub.transport': 'Transporte',
    'resources.sub.transport.desc':
      'El TAV de Taiwán conecta Taipéi con Kaohsiung en solo 90 minutos. Suma el metro, los sistemas de autobuses en tiempo real y YouBike — el transporte público de Taiwán es el campeón oculto de Asia.',
    'resources.sub.healthcare': 'Salud',
    'resources.sub.healthcare.desc':
      'Seguro de salud universal: una tarjeta, 99,9% de cobertura, 15 minutos de tiempo promedio de espera. Incluso EE. UU. estudia cómo lo hace Taiwán.',
    'resources.sub.finance': 'Finanzas y datos',
    'resources.sub.finance.desc':
      'La BVTM es uno de los mercados más transparentes de Asia. Desde los estados financieros de empresas cotizadas hasta datos de trading en tiempo real, todo es de acceso público.',
