    'resources.stats.subcategories': 'Subcategorías',
    'resources.search.placeholder': 'Buscar recursos...',
    'resources.aria.viewGithub': 'Ver repositorio de GitHub',
    'resources.aria.backToTop': 'Volver arriba',
    'resources.guide.title': 'Por dónde empezar',
    'resources.guide.desc':
      'Imagina aterrizar en Taiwán sin guía. La gobernanza te muestra el sistema operativo — cómo una democracia joven funciona con transparencia radical. La cultura es el alma — 500 museos, 15.000 festivales de templos al año y 16 lenguas indígenas en una isla más pequeña que Suiza. Los medios revelan la conversación — desde un foro de texto plano de 30 años que aún influye en las elecciones, hasta la redacción de noticias sin fines de lucro más audaz de Asia. La economía es el latido — una empresa fabrica el 92% de los chips avanzados del mundo, y la salud universal cuesta menos que tu factura de teléfono. La comunidad es la invitación — únete a los ciudadanos de código abierto que construyen herramientas cívicas en hackatones de fin de semana.',
    'resources.curator.government':
      '🔍 Durante la COVID-19, desarrolladores cívicos taiwaneses lanzaron mapas de mascarillas y sistemas de citas de vacunación en 72 horas. Detrás de esa velocidad: una plataforma de datos abiertos clasificada entre las 3 mejores del mundo — más de 50.000 conjuntos de datos, APIs en tiempo real, accesibles para cualquiera. Mientras desarrolladores en otros lugares esperaban conferencias de prensa gubernamentales, los de Taiwán ya estaban escribiendo código.',
    'resources.curator.culture':
      "🔍 Pocos saben que Taiwán tiene una de las mayores densidades de museos de Asia. Pero los números solo cuentan la superficie — lo verdaderamente especial es la cultura 'viva': más de 15.000 festivales de templos al año, 16 lenguas indígenas, competencias de canciones de montaña hakka. La cultura de Taiwán no está solo tras un cristal — camina por las calles.",
    'resources.curator.media':
      '🔍 ¿Qué tan influyente es PTT? Durante el referéndum de 2018, el volumen de discusión en el tablón de Gossiping de PTT se correlacionó directamente con la participación electoral. The Reporter es igualmente notable: un medio de investigación financiado por donaciones que ha sido nominado a premios de periodismo asiático durante años consecutivos. En una era de desinformación, Taiwán tiene simultáneamente la cultura de internautas más activa y la comunidad de verificación de hechos más dedicada — esta contradicción en sí misma es vitalidad democrática.',
    'resources.curator.economy':
      '🔍 Mientras las naciones debaten cuánto gastar en CHIPS Acts, Taiwán ya escribió la respuesta en obleas de silicio hace más de 30 años: una isla pequeña sin petróleo, sin mineral de hierro, posee el 92% de la producción global de chips avanzados gracias al talento puro y la ingeniería de precisión nanométrica. Ese número ganó una nueva palabra en informes del Pentágono — "escudo de silicio".',
    'resources.curator.community':
      '🔍 Los hackatones bimensuales de g0v se han realizado más de 60 veces, cada uno atrayendo a cientos de ingenieros, diseñadores y trabajadores de ONG voluntarios. Sin pago, sin jefe — solo una laptop y un problema que resolver. El mapa de mascarillas nació así: un fin de semana, unos pocos ingenieros, datos en tiempo real de 6.000 farmacias. Silicon Valley habla de cambiar el mundo. La comunidad de código abierto de Taiwán simplemente lo lanza.',
    'resources.featured.dataGov':
      'Clasificada como #1 a nivel mundial en datos abiertos gubernamentales — más de 50.000 conjuntos de datos desde calidad del aire hasta ubicaciones de autobuses en tiempo real, todos descargables gratuitamente.',
    'resources.featured.g0vGov':
      'Gov-zero: la comunidad de tecnología cívica que reescribe la gobernanza — desde mapas de mascarillas hasta vTaiwan, difuminando la línea entre hacker y formulador de políticas.',
    'resources.featured.legislativeYuan':
      'El parlamento de Taiwán — sesiones transmitidas en vivo, seguimiento de proyectos de ley y la primera línea de la deliberación democrática.',
    'resources.featured.npm':
      'Hogar de más de 700.000 artefactos que abarcan 8.000 años — una de las mayores colecciones de arte chino del mundo, ahora con exposiciones digitales de vanguardia.',
    'resources.featured.ncl':
      'La biblioteca nacional de Taiwán y centro de depósito legal — el archivo definitivo del conocimiento publicado de la nación.',
    'resources.featured.npgov':
      'Puerta de entrada a 9 parques nacionales — desde picos de 3.000 m hasta arrecifes de coral, cubriendo la extraordinaria biodiversidad de Taiwán en 36.000 km².',
    'resources.featured.twreporter':
      'Periodismo de investigación pionero sin fines de lucro en el mundo de habla china — inmersiones profundas en temas ambientales, sociales y políticos.',
    'resources.featured.ptt':
      'El foro en línea más grande de Taiwán — 200K usuarios activos diarios impulsando una singular "democracia impulsada por internautas" desde 1995.',
    'resources.featured.ptsNews':
      'Las noticias de la televisión pública de Taiwán — reportajes independientes, imparciales y el estándar de oro del periodismo de interés público.',
    'resources.featured.tsmc':
      'La empresa de semiconductores más valiosa del mundo, fabricando el 92% de los chips más avanzados que alimentan la IA, los smartphones y las supercomputadoras.',
    'resources.featured.twse':
      'El núcleo del mercado de capitales de Taiwán — hogar de TSMC, Foxconn y el motor de la economía tecnológica más dinámica de Asia.',
    'resources.featured.nhi':
      'Salud universal que cubre al 99,9% de la población con un 6,6% del PIB — un modelo estudiado por expertos en políticas sanitarias de todo el mundo.',
    'resources.featured.g0v':
      'La comunidad de tecnología cívica más impactante del mundo — generando el mapa de mascarillas de COVID, la plataforma de deliberación vTaiwan y un Ministro Digital.',
    'resources.featured.cofacts':
      'Verificación colaborativa de hechos en LINE — millones de usuarios combatiendo la desinformación con verificación asistida por IA.',
    'resources.featured.taiwanmd':
      'El proyecto que estás leyendo ahora mismo — una enciclopedia de código abierto, curada por la comunidad, sobre Taiwán.',
