    'resources.chapter.government.title':
      "Porte d'entrée vers la gouvernance nationale",
    'resources.chapter.government.story':
      'En février 2020, des ingénieurs taïwanais ont créé une carte en temps réel de la disponibilité des masques en un seul week-end, connectant 6 000 pharmacies. Une personne, un ordinateur portable, 72 heures — rendu possible grâce à data.gov.tw qui offre plus de 50 000 jeux de données gouvernementales prêts à être utilisés par tous, à tout moment. Taïwan a inscrit la « transparence de la gouvernance » dans chaque API téléchargeable.',
    'resources.chapter.culture.title': 'Culture et savoir',
    'resources.chapter.culture.story':
      'Sur moins de 36 000 kilomètres carrés, Taïwan abrite 159 universités, plus de 500 musées, 9 parcs nationaux, du mont Jade culminant à 3 952 mètres aux côtes de récifs coralliens. Le Musée national du Palais abrite près de 700 000 trésors culturels chinois, tandis que les festivals de temples de quartier sont un patrimoine culturel vivant tout aussi précieux. La densité culturelle de cette île dépasse largement sa taille sur une carte.',
    'resources.chapter.media.title': 'Les voix de Taïwan',
    'resources.chapter.media.story':
      "En 1995, des étudiants de l'NTU ont installé un serveur BBS dans leur dortoir, le nommant PTT. Trente ans plus tard, ce forum en texte brut reste la plateforme de discussion publique la plus influente de Taïwan — lors du Mouvement des Tournesols en 2014, PTT était la source d'informations en temps réel la plus rapide et la plus complète. L'écosystème médiatique de Taïwan, des journaux grand public aux forums de netizens, se bat pour la voix de la démocratie à chaque niveau.",
    'resources.chapter.economy.title': 'Économie et moteur de vie',
    'resources.chapter.economy.story':
      "Deux smartphones sur trois dans le monde contiennent une puce fabriquée par TSMC — les spécialistes géopolitiques l'appellent le « bouclier de silicium ». Mais les puces ne sont que la partie visible de l'iceberg : 99,9 % de couverture santé universelle, un magasin de proximité tous les 2,3 kilomètres carrés, des trains à grande vitesse reliant Taipei à Kaohsiung en 90 minutes. Ce qui soutient les 23 millions de vies quotidiennes est un système de précision si transparent que vous rempez à peine sa présence.",
    'resources.chapter.community.title': 'Tech civique et communauté',
    'resources.chapter.community.story':
      'La devise de g0v : « Ne demandez pourquoi personne ne le faites — vous êtes ce personne. » Cartes de masques, bots de vérification des faits, suiveurs de promesses électorales — tous nés de hackathons du week-end. À Taïwan, la participation civique ressemble à cela : écrire du code, ouvrir des tickets, soumettre des pull requests. COMPUTEX.md est un produit de cet esprit même.',
    'resources.insight.gov.branches.number': '5',
