    'resources.sub.fiveYuan': 'Branches constitutionnelles',
    'resources.sub.fiveYuan.desc':
      'Ces cinq branches forment le système pentapartite unique de Taïwan — le seul de son genre au monde.',
    'resources.sub.ministries': 'Ministères et agences',
    'resources.sub.ministries.desc':
      'Du ministère des Affaires numériques au Conseil des peuples autochtones, chaque ministère maintient son propre portail de données ouvertes.',
    'resources.sub.localGov': 'Gouvernements locaux',
    'resources.sub.localGov.desc':
      '22 comtés et villes, 22 styles de gouvernance locale. La course à la ville intelligente entre les six municipalités spéciales redéfinit les services publics.',
    'resources.sub.openData': 'Données ouvertes',
    'resources.sub.openData.desc':
      "C'est ici que commencent les miracles de la tech civique taïwanaise. Cartes de masques, réservation de vaccins, surveillance de la qualité de l'air — tout a commencé sur ces plateformes.",
    'resources.sub.universities': 'Universités et recherche de premier plan',
    'resources.sub.universities.desc':
      "Les universités de Taïwan ne se contentent pas d'enseigner — le laboratoire de calcul quantique de l'NTU et le centre de recherche en semi-conducteurs de la NCKU sont des nœuds vitaux du réseau académique mondial.",
    'resources.sub.museums': 'Musées et bibliothèques',
    'resources.sub.museums.desc':
      "Du Chou de jade du Musée national du Palais à la collection de violons du Musée Chimei, les musées de Taïwan sont des portails à travers le temps et l'espace.",
    'resources.sub.venues': 'Lieux artistiques et culturels',
    'resources.sub.venues.desc':
      "L'écosystème artistique de Taïwan prend son envol. C-LAB, Théâtre national, Weiwuying — une concentration de lieux de classe mondiale rivalisant avec New York.",
    'resources.sub.parks': 'Parcs nationaux et sites pittoresques',
    'resources.sub.parks.desc':
      'Du niveau de la mer à 3 952 mètres, les 9 parcs nationaux de Taïwan couvrent toutes les zones climatiques de la Terre. En une seule journée, vous pouvez passer des récifs coralliens tropicaux aux lignes de neige alpines.',
    'resources.sub.mainstream': 'Médias grand public',
    'resources.sub.mainstream.desc':
      "Depuis la levée des interdictions de presse après la fin de la loi martiale en 1988, jusqu'à la compétition des chaînes d'information en continu d'aujourd'hui — la liberté de la presse à Taïwan a été durement acquise.",
    'resources.sub.digital': 'Médias natifs numériques',
    'resources.sub.digital.desc':
      "Pendant que les médias traditionnels luttent, les médias natifs numériques de Taïwan redéfinissent le journalisme. Le modèle à but non lucratif du Reporter prouve que le journalisme d'investigation peut survivre sans publicité.",
    'resources.sub.ngo': 'Société civile et ONG',
    'resources.sub.ngo.desc':
      "Taïwan possède la plus forte densité d'ONG en Asie. De l'environnement aux droits humains, ces organisations ne se contentent pas de surveiller le gouvernement — elles montrent souvent la voie.",
    'resources.sub.companies': "Leaders de l'industrie",
    'resources.sub.companies.desc':
      "De TSMC à Foxconn, ces entreprises apparaissent dans les rapports de chaînes d'approvisionnement du monde entier.",
    'resources.sub.transport': 'Transports',
    'resources.sub.transport.desc':
      "Le TGV de Taïwan relie Taipei à Kaohsiung en seulement 90 minutes. Ajoutez le métro, les systèmes de bus en temps réel et YouBike — les transports en commun de Taïwan sont le champion caché de l'Asie.",
    'resources.sub.healthcare': 'Santé',
    'resources.sub.healthcare.desc':
      "Assurance maladie universelle : une carte, 99,9 % de couverture, 15 minutes d'attente moyenne. Même les États-Unis étudient comment Taïwan y parvient.",
    'resources.sub.finance': 'Finance et données',
    'resources.sub.finance.desc':
      "La TWSE est l'un des marchés les plus transparents d'Asie. Des états financiers des sociétés cotées aux données de trading en temps réel, tout est publiquement accessible.",
    'resources.sub.civicTech': 'Projets de tech civique',
    'resources.sub.foodMaps': 'Cartes culinaires et culturelles',
    'resources.related.democracy':
      'Voir aussi : Transition démocratique de Taïwan',
