    'resources.stats.collected': 'Ressources collectées',
    'resources.stats.chapters': 'Chapitres',
    'resources.stats.subcategories': 'Sous-catégories',
    'resources.search.placeholder': 'Rechercher des ressources...',
    'resources.aria.viewGithub': 'Voir le dépôt GitHub',
    'resources.aria.backToTop': 'Retour en haut',
    'resources.guide.title': 'Par où commencer',
    'resources.guide.desc':
      "Imaginez atterrir à Taïwan sans guide. La gouvernance vous montre le système d'exploitation — comment une jeune démocratie fonctionne avec une transparence radicale. La culture est l'âme — 500 musées, 15 000 festivals de temples annuels et 16 langues autochtones sur une île plus petite que la Suisse. Les médias révèlent la conversation — d'un forum en texte brut de 30 ans qui influence encore les élections, à la salle de rédaction à but non lucratif la plus audacieuse d'Asie. L'économie est le cœur battant — une entreprise fabrique 92 % des puces avancées du monde, et l'assurance maladie universelle coûte moins que votre facture de téléphone. La communauté est l'invitation — rejoignez les citoyens open source qui construisent des outils civiques lors de hackathons du week-end.",
    'resources.curator.government':
      '🔍 Pendant la COVID-19, des développeurs civiques taïwanais ont livré des cartes de masques et des systèmes de réservation de vaccins en 72 heures. Derrière cette vitesse : une plateforme de données ouvertes classée dans le top 3 mondial — plus de 50 000 jeux de données, des API en temps réel, accessibles à tous. Tandis que les développeurs ailleurs attendaient les conférences de presse gouvernementales, ceux de Taïwan écrivaient déjà du code.',
    'resources.curator.culture':
      "🔍 Peu de gens savent que Taïwan possède l'une des plus fortes densités de musées en Asie. Mais les chiffres ne racontent que la surface — ce qui est vraiment spécial, c'est la culture « vivante » : plus de 15 000 festivals de temples annuels, 16 langues autochtones, des concours de chants de montagne hakka. La culture de Taïwan n'est pas seulement derrière une vitrine — elle arpente les rues.",
    'resources.curator.media':
      "🔍 Quelle est l'influence de PTT ? Lors du référendum de 2018, le volume de discussion sur le forum Gossiping de PTT était directement corrélé à la participation électorale. Le Reporter est tout aussi remarquable : un média d'investigation financé par des dons, nominé pendant des années consécutives aux prix du journalisme asiatique. À l'ère de la désinformation, Taïwan possède simultanément la culture de netizens la plus active et la communauté de vérification des faits la plus dévouée — cette contradiction elle-même est la vitalité démocratique.",
    'resources.curator.economy':
      "🔍 Tandis que les nations débattent du montant à consacrer aux CHIPS Acts, Taïwan a déjà écrit la réponse sur des wafers de silicium il y a plus de 30 ans : une petite île sans pétrole, sans minerai de fer, détient 92 % de la production mondiale de puces avancées grâce au talent pur et à l'ingénierie de précision au nanomètre. Ce chiffre a mérité un nouveau mot dans les rapports du Pentagone — « bouclier de silicium ».",
    'resources.curator.community':
      "🔍 Les hackathons bimensuels de g0v ont eu lieu plus de 60 fois, attirant à chaque fois des centaines d'ingénieurs, de designers et de travailleurs d'ONG bénévoles. Pas de salaire, pas de patron — juste un ordinateur portable et un problème à résoudre. La carte des masques est née ainsi : un week-end, quelques ingénieurs, des données en temps réel de 6 000 pharmacies. Silicon Valley parle de changer le monde. La communauté open source de Taïwan le livre simplement.",
    'resources.featured.dataGov':
      "Classé n°1 mondial pour les données ouvertes gouvernementales — plus de 50 000 jeux de données, de la qualité de l'air aux positions de bus en temps réel, tous téléchargeables gratuitement.",
    'resources.featured.g0vGov':
      'Gov-zero : la communauté de tech civique qui réécrit la gouvernance — des cartes de masques à vTaiwan, brouillant la frontière entre hacker et décideur politique.',
    'resources.featured.legislativeYuan':
      'Le parlement de Taïwan — sessions en direct, suivi des projets de loi et première ligne de la délibération démocratique.',
    'resources.featured.npm':
      "Abritant plus de 700 000 artefacts couvrant 8 000 ans — l'une des plus grandes collections d'art chinois au monde, désormais avec des expositions numériques de pointe.",
    'resources.featured.ncl':
      "La bibliothèque nationale de Taïwan et centre de dépôt légal — l'archive définitive des connaissances publiées de la nation.",
    'resources.featured.npgov':
      "Porte d'entrée vers 9 parcs nationaux — des sommets de 3 000 m aux récifs coralliens, couvrant la biodiversité extraordinaire de Taïwan sur 36 000 km².",
    'resources.featured.twreporter':
      "Journalisme d'investigation à but non lucratif pionnier dans le monde sinophone — plongées approfondies dans les questions environnementales, sociales et politiques.",
    'resources.featured.ptt':
      'Le plus grand forum en ligne de Taïwan — 200 000 utilisateurs actifs quotidiens animant une « démocratie portée par les netizens » depuis 1995.',
    'resources.featured.ptsNews':
      "L'information de la télévision publique de Taïwan — reportage indépendant et impartial, référence en journalisme d'intérêt public.",
    'resources.featured.tsmc':
      "La société de semi-conducteurs la plus précieuse au monde, fabriquant 92 % des puces les plus avancées alimentant l'IA, les smartphones et les superordinateurs.",
    'resources.featured.twse':
      "Le cœur du marché des capitaux de Taïwan — abritant TSMC, Foxconn et le moteur de l'économie technologique la plus dynamique d'Asie.",
    'resources.featured.nhi':
      'Assurance maladie universelle couvrant 99,9 % de la population à 6,6 % du PIB — un modèle étudié par les experts en politique de santé du monde entier.',
    'resources.featured.g0v':
      'La communauté de tech civique la plus impactante au monde — ayant donné naissance à la carte de masques COVID, à la plateforme de délibération vTaiwan et à un ministre du Numérique.',
    'resources.featured.cofacts':
      "Vérification collaborative des faits sur LINE — des millions d'utilisateurs luttant contre la désinformation avec une vérification assistée par IA.",
    'resources.featured.taiwanmd':
      'Le projet que vous êtes en train de lire — une encyclopédie open source, organisée par la communauté, sur Taïwan.',
